mapper.select:
SELECT sc.CONFIG_ID, sc.DICT_CODE, sc.SCHEME_TYPE, scv.CONFIG_VALUE, plan.BOOKSET_ID FROM BOK_SCHEME_CONFIG sc INNER JOIN BOK_SCHEME_CONFIG_VAL scv ON scv.CONFIG_ID = sc.CONFIG_ID INNER JOIN BOK_BOOKSET_PLAN plan ON scv.SCHEME_ID = plan.SCHEME_ID AND sc.SCHEME_TYPE = plan.SCHEME_TYPE
plan.BOOKSET_ID = #{booksetId} AND sc.SCHEME_TYPE = #{schemeType}
ORDER BY plan.BOOKSET_ID,sc.SCHEME_TYPE

SELECT BOK_SCENECONFIG.SCENE_NODE_ID "sceneNodeId", BOK_SCENECONFIG.FSCENE_NODEID "fSceneNodeId", BOK_SCENECONFIG.BOOKSET_ID "booksetId", NVL(BOK_TABLEDICT.DICT_CODE, BOK_SCENECONFIG.NODE_ID) "nodeId", BOK_SCENECONFIG.NODE_VALUE "nodeValue", SCIDS.NODE_VALUE accountSceneCode FROM BOK_SCENECONFIG BOK_SCENECONFIG INNER JOIN BOK_SCENECONFIG SCIDS ON SCIDS.BOOKSET_ID = BOK_SCENECONFIG.BOOKSET_ID AND SCIDS.NODE_ID = #{ACCOUNTEVENTS} AND INSTR(BOK_SCENECONFIG.SCENE_NODE_ID, SCIDS.SCENE_NODE_ID) = 1 LEFT JOIN BOK_TABLEDICT BOK_TABLEDICT ON BOK_TABLEDICT.BOOKSET_ID = BOK_SCENECONFIG.BOOKSET_ID AND BOK_TABLEDICT.DICT_ID = BOK_SCENECONFIG.NODE_ID
BOK_SCENECONFIG.BOOKSET_ID = #{booksetId}
ORDER BY BOK_SCENECONFIG.SCENE_NODE_ID

SELECT BOK_SCENESUBJECT.SCENE_NODE_ID "sceneNodeId", BOK_SCENESUBJECT.SUBJECT_NO "subjectId", BOK_SCENESUBJECT.CD_FLAG "cdFlag", BOK_TABLEDICT.DICT_CODE "formElement", BOK_SCENESUBJECT.ACCOUNT_NET "accountNet", BOK_SUBJECT.SUBJECT_NAME subjectName, BOK_SUBJECT.FSUBJECT_ID fsubjectId, BOK_SUBJECT.BASE_SUBJECT_NATURE "baseSubjectNature", BOK_SUBJECT.SUBJECT_TYPE "subjectType", BOK_SUBJECT.ACC_QUA_FLAG "accQuaFlag", BOK_SUBJECT.ACC_INT_FLAG "accIntFlag", BOK_SUBJECT.OVERDRAWN_FLAG "overdrawnFlag", BOK_SUBJECT.GEN_DETSUB_FLAG "genDetsubFlag", BOK_SUBJECT.BAL_FLAG "balFlag", SCIDS.NODE_VALUE "nodeValue", BOK_SCENESUBJECT.BOK_DETAIL_ID "bokDetailId", BOK_SCENESUBJECT.BOOKSET_ID booksetId FROM BOK_SCENESUBJECT BOK_SCENESUBJECT INNER JOIN BOK_SCENECONFIG SCIDS ON SCIDS.NODE_ID = #{ACCOUNTEVENTS} AND SCIDS.BOOKSET_ID = BOK_SCENESUBJECT.BOOKSET_ID AND INSTR(BOK_SCENESUBJECT.SCENE_NODE_ID, SCIDS.SCENE_NODE_ID) = 1 LEFT JOIN BOK_SUBJECT BOK_SUBJECT ON BOK_SUBJECT.BOOKSET_ID = BOK_SCENESUBJECT.BOOKSET_ID AND BOK_SCENESUBJECT.SUBJECT_NO = BOK_SUBJECT.SUBJECT_NO LEFT JOIN BOK_TABLEDICT BOK_TABLEDICT ON BOK_TABLEDICT.BOOKSET_ID = BOK_SCENESUBJECT.BOOKSET_ID AND BOK_TABLEDICT.DICT_ID = BOK_SCENESUBJECT.FORM_ELE
BOK_SCENESUBJECT.BOOKSET_ID = #{booksetId}
ORDER BY BOK_SCENESUBJECT.SCENE_NODE_ID
